const ContactForm = () => {
  const [errors, setErrors] = useState({});
  const fullNameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const newErrors = {};

    if (!formData.get('fullName').trim()) {
      newErrors.fullName = 'Error: Full name is required.';
    }

    const email = formData.get('email').trim();
    if (!email) {
      newErrors.email = 'Error: Email address is required.';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      newErrors.email = 'Error: Enter a valid email address.';
    }

    const phone = formData.get('phone').trim();
    if (phone && !/^\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/.test(phone)) {
      newErrors.phone = 'Error: Phone number format is invalid.';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      if (newErrors.fullName) {
        fullNameRef.current.focus();
      } else if (newErrors.email) {
        emailRef.current.focus();
      } else if (newErrors.phone) {
        phoneRef.current.focus();
      }
    } else {
      setErrors({});
      // Success case
      alert("Support request submitted successfully.");
    }
  };

  return (
    <div className="support-form-container">
      <main>
        <h1>Support Contact</h1>
        <p className="help-text" style={{ marginBottom: '1.5rem' }}>
          Fields marked with an asterisk (<span className="required-marker" aria-hidden="true">*</span>) are required.
        </p>
        <form noValidate onSubmit={handleSubmit}>
          <div className="form-field">
            <label htmlFor="fullName">
              Full name <span className="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="fullName"
              name="fullName"
              type="text"
              required
              autoComplete="name"
              ref={fullNameRef}
              aria-describedby={errors.fullName ? "fullName-error" : undefined}
              aria-invalid={!!errors.fullName}
            />
            {errors.fullName && <p id="fullName-error" className="error-text">{errors.fullName}</p>}
          </div>

          <div className="form-field">
            <label htmlFor="email">
              Email address <span className="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              required
              autoComplete="email"
              ref={emailRef}
              aria-describedby={errors.email ? "email-error" : undefined}
              aria-invalid={!!errors.email}
            />
            {errors.email && <p id="email-error" className="error-text">{errors.email}</p>}
          </div>

          <div className="form-field">
            <label htmlFor="phone">
              Phone number (optional)
            </label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autoComplete="tel"
              ref={phoneRef}
              aria-describedby="phone-help"
            />
            <p id="phone-help" className="help-text">
              Format: (XXX) XXX-XXXX or XXX-XXX-XXXX
            </p>
          </div>

          <button type="submit">Submit Request</button>
        </form>
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);', path=None, possible_paths=None, possible_urls=None, read_only=None, reason=None, server_name=None, subject=None, tool_args=None, tool_call_id='function-call-07727ce7-1c75-4c4b-a167-d80b72d6fc62', tool_description=None, tool_name=None, tool_title=None, url=None, warning=None)

